.log-entry{display:flex;gap:8px;animation:logArrive .25s ease-out}.log-entry:before{content:'›';color:var(--lime);font:13px var(--mono);flex:none}.log-entry.old{color:#82928b}
.sidebar-foot{margin-top:auto;display:flex;justify-content:space-between;color:#73847c;font-size:8px;padding:2px 3px}
