function ration(){
  if(state.ended||state.rations<1||state.hp===state.maxHp)return;
  state.rations--;
  const heal=Math.min(10,state.maxHp-state.hp),crewHeal=state.team.some(c=>c.hp<c.maxHp);
  state.hp+=heal;
  for(const c of state.team)c.hp=Math.min(c.maxHp,c.hp+4);
  state.turn++;
  log(`Field ration restored ${heal} vitality. Crew recovered.`);
