.page-footer{display:flex;justify-content:space-between;padding:14px 0 20px;border-top:1px solid #253531;color:#778a80;font-size:8px;letter-spacing:.8px}

/* Units are layered as small isometric miniatures; the sprite, shadow and rim
   light stay separate so movement and combat remain readable on every tile. */
.unit-figure{--unit-glow:#c2efa0;position:relative;z-index:2;width:100%;height:100%;display:grid;place-items:center;transform-style:preserve-3d;will-change:transform,filter}.unit-figure:before{content:"";position:absolute;left:50%;bottom:13%;width:62%;height:20%;transform:translateX(-50%) rotateX(58deg) translateZ(-5px);border-radius:50%;background:#070e0dcc;filter:blur(2px);box-shadow:0 3px 8px #0008}.unit-figure:after{content:"";position:absolute;left:50%;bottom:20%;width:50%;height:52%;transform:translateX(-50%) translateZ(-3px);border-radius:48% 48% 38% 38%;background:linear-gradient(135deg,#d9f4b433,#283c31aa 55%,#111d1d);border:1px solid #d6efb022;box-shadow:inset 2px 2px 4px #f4ffce22,inset -3px -4px 5px #07100e99,2px 4px 3px #08100d88}.sprite{position:relative;z-index:1;display:grid;place-items:center;line-height:1;font-family:var(--sans);font-size:clamp(17px,2.1vw,30px);filter:drop-shadow(1px 2px 0 #15221b) drop-shadow(0 5px 3px #0009);transform:translateY(-3px) translateZ(8px);text-shadow:0 0 12px #d9ffb733;animation:unitIdle 3.2s ease-in-out infinite}.player .sprite{font-size:clamp(19px,2.25vw,32px);filter:drop-shadow(2px 3px 0 #31452c) drop-shadow(0 6px 4px #000a)}.player:after{border-color:#d8f48766;background:linear-gradient(135deg,#efffc744,#526b3eaa 60%,#1d2c25);box-shadow:inset 2px 2px 6px #efffc944,inset -3px -4px 5px #07100e99,0 0 11px #d8f48733}.enemy{--unit-glow:#ff947d}.enemy:after{border-color:#ffb19a45;background:linear-gradient(135deg,#ffd0a833,#73443caa 60%,#2a2527);box-shadow:inset 2px 2px 5px #ffd4be33,inset -3px -4px 5px #160f11aa,0 0 9px #fa836033}.boss-tile .enemy:after{background:linear-gradient(135deg,#f8b6a044,#62333daa 60%,#211925);box-shadow:inset 2px 2px 5px #ffd4be44,inset -3px -4px 5px #160f11aa,0 0 15px #f57d7b55}.exit-unit{--unit-glow:#a5e3c5}.exit-unit .sprite{font-size:clamp(14px,1.8vw,23px);color:#b4e9c9;text-shadow:0 0 10px #9aebca99;animation:exitPulse 2.4s ease-in-out infinite}.item-unit{--unit-glow:#f2d783}.item-unit:after{width:37%;height:36%;bottom:25%;border-radius:35%;transform:translateX(-50%) rotate(45deg) translateZ(2px);background:linear-gradient(135deg,#fff1ad,#9a7939 65%,#4c472c);border-color:#ffeca955;box-shadow:inset 2px 2px 3px #fff7c777,2px 4px 4px #080f0caa}.item-unit:before{bottom:19%;width:44%;height:15%}.item-unit .sprite{font-size:clamp(14px,1.7vw,22px);color:#fff0a9;animation:lootHover 2.1s ease-in-out infinite}.hp-pip{position:absolute;z-index:4;bottom:5%;left:18%;width:64%;height:3px;overflow:hidden;border:1px solid #111a17;border-radius:4px;background:#19221f}.hp-pip i{display:block;height:100%;background:linear-gradient(90deg,#eb766b,#ffd087);box-shadow:0 0 5px #ff8c70;transition:width .2s}.boss-tile .hp-pip{height:4px;box-shadow:0 0 6px #f17d6a77}
.tile.player-tile{background:linear-gradient(145deg,#4a5d43,#354a38 62%,#26372f);box-shadow:inset 0 1px #efffc72b,inset 0 -3px #101b17,0 3px #101b17,0 0 14px #c5eb8b24}.tile.enemy-tile{background:linear-gradient(145deg,#4e443c,#3a3732 65%,#2b302b)}.tile.boss-tile{background:linear-gradient(145deg,#573c3d,#402e34 65%,#2b242b);box-shadow:inset 0 1px #ffb59a33,inset 0 -3px #1a1117,0 3px #101719,0 0 16px #f1817655}.tile.item-tile{background:linear-gradient(145deg,#514a34,#3b3b2b 65%,#293329)}.tile.exit-tile{background:linear-gradient(145deg,#345346,#263c39 65%,#1d302d)}.tile.exit-tile:before{content:"";position:absolute;inset:18%;border:1px solid #a4dfbf55;border-radius:50%;box-shadow:0 0 12px #8ee1b833;animation:exitRing 2.4s ease-in-out infinite}.tile.attack-player-strike .unit-figure,.tile.attack-crew-strike .unit-figure{animation:unitHit .42s cubic-bezier(.2,.8,.25,1) both}.tile.attack-enemy-hit .unit-figure{animation:playerRecoil .45s ease-out both}.tile.attack-capture .unit-figure{animation:captured .48s ease-in both}.tile.attack-pulse-shock .unit-figure{animation:pulseShock .48s ease-out both}.tile.attack-player-strike:after,.tile.attack-crew-strike:after{content:"";position:absolute;z-index:5;inset:10%;border:2px solid #ffb183;border-radius:50%;animation:strikeFlash .36s ease-out both;pointer-events:none}.tile.attack-enemy-hit:after{content:"";position:absolute;z-index:5;inset:9%;border:2px solid #ffa18b;border-radius:50%;animation:hitFlash .4s ease-out both;pointer-events:none}.tile.attack-capture:after,.tile.attack-pulse-shock:after{content:"";position:absolute;z-index:5;inset:6%;border:2px solid #c6f5a1;border-radius:50%;box-shadow:0 0 12px #c6f5a1aa;animation:pulseRing .48s ease-out both;pointer-events:none}.tile.attack-capture .sprite{filter:drop-shadow(0 0 10px #c9ffa3)}.move-vault-up{animation:vaultUp .62s cubic-bezier(.25,.72,.28,1) both}.move-vault-down{animation:vaultDown .62s cubic-bezier(.25,.72,.28,1) both}.move-vault-left{animation:vaultLeft .62s cubic-bezier(.25,.72,.28,1) both}.move-vault-right{animation:vaultRight .62s cubic-bezier(.25,.72,.28,1) both}.enemy.move-vault-up,.enemy.move-vault-down,.enemy.move-vault-left,.enemy.move-vault-right{animation-duration:.54s}.hit-flash{animation:frameHit .24s ease-out}.depth-warp{animation:depthWarp .58s cubic-bezier(.5,0,.7,1)}.board.reveal .tile{animation:tileReveal .5s both;animation-delay:calc(var(--n)*8ms)}
.fx-pop{position:absolute;z-index:2;transform:translate(-50%,-50%);font:700 15px var(--display);text-shadow:0 2px 5px #000;animation:popText .85s ease-out forwards;white-space:nowrap}.fx-particle{position:absolute;width:5px;height:5px;border-radius:50%;box-shadow:0 0 8px currentColor;animation:particleBurst .65s ease-out forwards}
@keyframes unitIdle{0%,100%{transform:translateY(-3px) translateZ(8px) rotate(-2deg)}50%{transform:translateY(-6px) translateZ(8px) rotate(2deg)}}@keyframes lootHover{0%,100%{transform:translateY(-3px) translateZ(8px) rotate(-8deg)}50%{transform:translateY(-8px) translateZ(8px) rotate(8deg)}}@keyframes exitPulse{0%,100%{transform:translateY(-3px) translateZ(8px) scale(.92)}50%{transform:translateY(-4px) translateZ(8px) scale(1.08)}}@keyframes exitRing{0%,100%{transform:scale(.88);opacity:.45}50%{transform:scale(1.08);opacity:.9}}
@keyframes vaultUp{0%{transform:translateY(0) scale(1)}28%{transform:translateY(-15px) scale(1.12) rotateX(12deg);filter:brightness(1.45)}65%{transform:translateY(-9px) scale(1.08)}100%{transform:translateY(0) scale(1)}}@keyframes vaultDown{0%{transform:translateY(0) scale(1)}28%{transform:translateY(-15px) scale(1.12) rotateX(-12deg);filter:brightness(1.4)}65%{transform:translateY(-9px) scale(1.08)}100%{transform:translateY(0) scale(1)}}@keyframes vaultLeft{0%{transform:translateX(0) scale(1)}28%{transform:translate(-6px,-14px) scale(1.12) rotateY(-16deg);filter:brightness(1.45)}65%{transform:translate(-3px,-8px) scale(1.08)}100%{transform:translate(0) scale(1)}}@keyframes vaultRight{0%{transform:translateX(0) scale(1)}28%{transform:translate(6px,-14px) scale(1.12) rotateY(16deg);filter:brightness(1.45)}65%{transform:translate(3px,-8px) scale(1.08)}100%{transform:translate(0) scale(1)}}
@keyframes unitHit{0%,100%{transform:scale(1)}20%{transform:translateX(-5px) rotate(-9deg) scale(.9);filter:brightness(1.8) saturate(.5)}50%{transform:translateX(4px) rotate(6deg) scale(1.08)}75%{transform:translateX(-2px) rotate(-3deg)}}@keyframes playerRecoil{0%,100%{transform:translateX(0)}22%{transform:translateX(8px) rotate(12deg) scale(.9);filter:brightness(1.8)}55%{transform:translateX(-4px) rotate(-5deg)}}@keyframes captured{0%{transform:scale(1);opacity:1}40%{transform:scale(1.2);filter:brightness(2) drop-shadow(0 0 10px #caff9f)}100%{transform:scale(.05) translateY(-12px);opacity:0}}@keyframes pulseShock{0%,100%{transform:scale(1)}25%{transform:scale(1.2);filter:brightness(2) hue-rotate(25deg)}65%{transform:scale(.85) rotate(7deg)}}@keyframes strikeFlash{0%{transform:scale(.2) rotate(0);opacity:1}100%{transform:scale(1.3) rotate(35deg);opacity:0}}@keyframes hitFlash{0%{opacity:1;box-shadow:inset 0 0 15px #ff7b6555}100%{opacity:0;transform:scale(1.12)}}@keyframes pulseRing{0%{transform:scale(.2);opacity:1}100%{transform:scale(1.35);opacity:0}}@keyframes frameHit{0%,100%{filter:none}35%{filter:brightness(1.32) sepia(.18)}}@keyframes depthWarp{0%{filter:none;transform:scale(1)}45%{filter:brightness(1.8) hue-rotate(30deg);transform:scale(.97)}100%{filter:none;transform:scale(1)}}@keyframes tileReveal{from{opacity:0;transform:translateY(8px) scale(.9)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes popText{0%{opacity:0;transform:translate(-50%,-20%)}18%{opacity:1;transform:translate(-50%,-80%)}100%{opacity:0;transform:translate(-50%,-150%)}}@keyframes particleBurst{0%{opacity:1;transform:translate(-50%,-50%) scale(1)}100%{opacity:0;transform:translate(calc(-50% + var(--dx)),calc(-50% + var(--dy))) scale(.1)}}@keyframes livePulse{50%{box-shadow:0 0 2px #a6e9a1;opacity:.65}}@keyframes sigilDrift{50%{transform:rotate(45deg) scale(1.08)}}
@media(max-width:1050px){.app-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 275px;gap:18px}.board{grid-template-rows:repeat(9,minmax(27px,1fr));gap:3px;padding:10px 11px 14px}.panel{padding:12px}.sprite{font-size:clamp(16px,2.5vw,27px)}}@media(max-width:780px){.app-shell{padding:0 18px}.game-layout{grid-template-columns:1fr;gap:10px;padding-top:23px}.sidebar{display:grid;grid-template-columns:1fr 1fr;align-items:stretch}.operator-panel{grid-row:span 2}.journal-panel{min-height:0}.log{height:126px}.sidebar-foot{grid-column:1/-1}.board{grid-template-rows:repeat(9,minmax(30px,1fr))}.sprite{font-size:clamp(16px,3.8vw,29px)}.page-footer{gap:12px}.page-footer span:last-child{text-align:right}}@media(max-width:520px){.app-shell{padding:0 12px}.topbar{height:60px}.brand{font-size:15px}.brand-mark{font-size:21px}.run-stamp{font-size:8px;gap:6px}.game-layout{padding-top:18px}.section-heading h1{font-size:20px}.section-heading .eyebrow{font-size:8px}.floor-subtitle{font-size:11px}.depth-track{font-size:7px}.depth-track i{width:19px}.board{grid-template-rows:repeat(9,minmax(22px,1fr));gap:2px;padding:8px 7px 11px}.map-topline,.map-footer{height:31px;padding:0 8px;font-size:7px}.fx-layer{inset:31px 0 31px}.tile.wall:after{inset:3px 3px auto}.sprite{font-size:clamp(13px,4.6vw,22px)}.player .sprite{font-size:clamp(15px,5vw,24px)}.hp-pip{height:2px}.map-footer{gap:5px}.legend{margin-right:1px}.turn-counter{font-size:7px}.controls-row{padding:11px 2px}.action-copy>span:last-child{max-width:205px;font-size:10px}.dpad{grid-template-columns:repeat(3,32px);grid-template-rows:repeat(2,30px)}.sidebar{grid-template-columns:1fr;gap:9px}.operator-panel{grid-row:auto}.journal-panel{min-height:155px}.log{height:105px}.page-footer{font-size:7px;line-height:1.5}.modal-card{width:min(440px,calc(100vw - 28px));padding:32px 25px!important}.modal-card h2{font-size:37px!important}.howto{flex-direction:column;gap:10px!important}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

