 :root{color-scheme:dark;--bg:#0b1118;--panel:#131e27;--panel2:#18252e;--line:#2b3b40;--muted:#91a19e;--text:#eef3e9;--mint:#b6edc4;--lime:#d8f487;--coral:#ff8676;--yellow:#f6cb70;--teal:#7ac4b0;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
 *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;overflow-x:hidden;background:radial-gradient(ellipse at 68% -12%,#34473b55,transparent 36%),radial-gradient(ellipse at 12% 45%,#15283265,transparent 42%),var(--bg);color:var(--text);font:14px var(--sans)}body:before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E")}button{font:inherit;color:inherit}.app-shell{max-width:1510px;margin:auto;padding:0 40px}.topbar{height:74px;border-bottom:1px solid #29383a;display:flex;align-items:center;justify-content:space-between;position:relative}.topbar:after{content:"";position:absolute;bottom:-1px;left:0;width:130px;height:1px;background:var(--lime);box-shadow:0 0 12px #d8f48755}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--text);font:700 18px var(--display);letter-spacing:1.6px}.brand-mark{font-size:25px;color:var(--lime);text-shadow:0 0 18px #d8f48777;animation:sigilDrift 5s ease-in-out infinite}.brand-dot{color:var(--lime)}.run-stamp,.eyebrow,.panel-title,.map-topline,.map-footer,.floor-badge,.sidebar-foot,.page-footer,.modal-kicker,.save-note,.howto,.stat-line,.operator-profile p,.depth-track{font-family:var(--mono);letter-spacing:1px}.run-stamp{color:#a7b5af;font-size:10px;display:flex;align-items:center;gap:11px}.stamp-divider{color:#53625e}.live-dot{height:7px;width:7px;border-radius:100%;background:#a6e9a1;box-shadow:0 0 10px #a6e9a1;animation:livePulse 2s infinite}.icon-button{width:36px;height:36px;border:1px solid var(--line);border-radius:50%;background:#142029;color:#aab8ad;cursor:pointer}.icon-button:hover,.icon-button.sound-on{color:var(--lime);border-color:#a6c76f}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:26px;padding:31px 0 24px}.main-column{min-width:0}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.eyebrow{font-size:9px;color:#91aaa0;margin:0 0 9px}.eyebrow-divider{color:#718b72;margin:0 7px}.section-heading h1{font:700 clamp(20px,2.4vw,30px)/1.1 var(--display);letter-spacing:.3px;margin:0}.section-heading h1 span{font:500 12px var(--mono);color:var(--lime);vertical-align:middle;margin-left:5px}.floor-subtitle{margin:8px 0 0;color:#9eaca5;font-size:12px}.floor-badge{display:flex;align-items:baseline;gap:5px;color:#81918b;font-size:9px;white-space:nowrap}.floor-badge strong{font:600 25px var(--display);color:var(--lime)}.depth-track{display:flex;align-items:center;gap:5px;margin:0 0 13px;color:#71827c;font-size:8px}.depth-track i{height:3px;width:27px;background:#34443f;border-radius:4px}.depth-track i.active{background:#728d5d}.depth-track i.current{background:var(--lime);box-shadow:0 0 9px #d8f48777}.depth-track span{margin-left:7px}.game-frame{position:relative;overflow:hidden;border:1px solid #3c5049;border-radius:5px;background:#111c20;box-shadow:0 16px 42px #0005,inset 0 1px #ffffff08;perspective:900px}.map-topline,.map-footer{height:37px;padding:0 15px;display:flex;align-items:center;justify-content:space-between;color:#91a49a;background:#152128;font-size:9px}.map-topline{border-bottom:1px solid #2b3b3a}.map-topline>span:first-child{color:#c3d1c5}.tiny-square{display:inline-block;width:6px;height:6px;background:var(--lime);margin-right:7px;box-shadow:0 0 8px #d8f48777}.map-coords{color:#b5c29d}.board{display:grid;grid-template-columns:repeat(13,minmax(0,1fr));grid-template-rows:repeat(9,minmax(32px,1fr));aspect-ratio:13/9;padding:12px 14px 17px;gap:4px;position:relative;isolation:isolate;background:radial-gradient(ellipse at 50% 45%,#24352e 0%,#172522 72%,#14201e 100%);transform-style:preserve-3d}.board:before{content:"";position:absolute;inset:10px 12px 15px;z-index:-1;pointer-events:none;opacity:.2;background-image:linear-gradient(#88aa7940 1px,transparent 1px),linear-gradient(90deg,#88aa7940 1px,transparent 1px);background-size:calc(100% / 13) calc(100% / 9)}.tile{position:relative;display:grid;place-items:center;min-width:0;border-radius:3px;background:linear-gradient(145deg,#435343,#2b3c35 62%,#26372f);box-shadow:inset 0 1px #c5d49812,inset 0 -3px #0a1512aa,0 3px 0 #101b17;transform-style:preserve-3d;transition:filter .2s,background .2s}.tile.floor:nth-child(4n){background:linear-gradient(145deg,#3b4a3e,#283a32 65%,#24352e)}.tile.floor:nth-child(7n){background:linear-gradient(145deg,#35483e,#26372f 70%,#1d302b)}.tile.wall{background:linear-gradient(145deg,#374542,#263633 55%,#1d2b2b);box-shadow:inset 0 2px #a2b79c22,inset 0 -5px #0d1919,0 4px 0 #101a19,0 6px 12px #07100e88}.tile.wall:after{content:"";position:absolute;inset:4px 5px auto;height:1px;background:#c2d0aa16;box-shadow:0 5px #b1c19b0c,0 11px #b1c19b0b}.tile:not(.wall):hover{filter:brightness(1.15)}.map-footer{height:35px;border-top:1px solid #2b3b3a;font-size:8px;gap:12px}.legend{font-size:11px;font-style:normal;margin-right:4px}.player-legend{color:#c9efab}.enemy-legend{color:#f18a78}.loot-legend{color:#e8ce78}.exit-legend{color:#a3d8c0}.turn-counter{margin-left:auto;color:#bfceae}.fx-layer{position:absolute;inset:37px 0 35px;z-index:8;pointer-events:none;overflow:hidden}.game-toast{position:absolute;z-index:10;left:50%;top:50%;transform:translate(-50%,-50%) translateY(8px);padding:10px 16px;border:1px solid #a8c98766;border-radius:3px;background:#111d1deF;color:var(--lime);font:10px var(--mono);letter-spacing:1px;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap}.game-toast.show{opacity:1;transform:translate(-50%,-50%)}
 .controls-row{display:flex;align-items:center;justify-content:space-between;padding:15px 3px}.action-copy{display:grid;gap:6px}.action-copy .eyebrow{margin:0}.action-copy>span:last-child{font-size:12px;color:#c0cbc0}.dpad{display:grid;grid-template-columns:repeat(3,36px);grid-template-rows:repeat(2,34px);gap:4px}.dpad button{border:1px solid #3b5048;border-radius:4px;background:linear-gradient(#20312e,#172521);color:#c5d6bd;font-size:17px;cursor:pointer;box-shadow:0 2px #0d1715;transition:.15s}.dpad button:nth-child(1){grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.dpad button:hover{color:var(--lime);border-color:#819b65;transform:translateY(-1px)}.dpad button:active{transform:translateY(1px);box-shadow:none}
 .sidebar{display:flex;flex-direction:column;gap:12px}.panel{border:1px solid #2e403e;border-radius:4px;background:linear-gradient(145deg,#18262d,#131f26);padding:14px 15px;box-shadow:0 8px 20px #0002}.panel-title{height:18px;display:flex;justify-content:space-between;align-items:center;color:#a9b9ae;font-size:9px}.status-pill{border:1px solid #59765a;border-radius:10px;padding:3px 7px;color:#b5dc9b;font-size:8px}.operator-profile{display:flex;align-items:center;gap:12px;margin:17px 0 16px}.operator-avatar{height:43px;width:43px;display:grid;place-items:center;border:1px solid #68815c;border-radius:50%;background:radial-gradient(circle,#45583c,#202d2a 68%);color:var(--lime);font-size:25px;box-shadow:0 0 16px #b6edc422}.operator-profile h2{margin:0 0 5px;font:600 13px var(--display);letter-spacing:1px}.operator-profile p{margin:0;color:#94a69c;font-size:9px}.sep{margin:0 5px;color:#637c70}.stat-line{display:flex;justify-content:space-between;align-items:center;color:#a8b8ac;font-size:9px}.stat-line strong{color:#e4eedc;font-weight:500}.meter,.creature-mini-meter{height:5px;overflow:hidden;border-radius:4px;background:#293934}.meter{margin:7px 0 14px}.meter i,.creature-mini-meter i{display:block;height:100%;border-radius:inherit;transition:width .25s}.resource-line{margin-bottom:13px}.operator-actions{display:grid;gap:7px}.action-button{width:100%;height:35px;display:flex;align-items:center;gap:8px;padding:0 10px;border:1px solid #647b4f;border-radius:3px;background:linear-gradient(110deg,#3a4b36,#293b32);color:#e2edcf;font-size:9px;letter-spacing:.7px;cursor:pointer}.action-button>span{font-size:16px;color:var(--lime)}.action-button kbd{margin-left:auto}.action-button.secondary{border-color:#354b47;background:#1a2b2c;color:#c2d2c8}.action-button:disabled{opacity:.42;cursor:not-allowed;filter:saturate(.5)}.action-button:not(:disabled):hover{filter:brightness(1.18)}kbd{font:9px var(--mono);padding:3px 5px;border:1px solid #536459;border-radius:2px;background:#101b1a;color:#c4d2c1}.action-button small{margin-left:auto;color:#d4e4b7}.team-panel{padding-bottom:11px}.team-list{display:grid;gap:8px;margin-top:12px}.team-creature{display:flex;align-items:center;gap:9px;padding:8px;border:1px solid #2c403b;border-radius:3px;background:#182824}.creature-avatar{width:34px;height:34px;display:grid;place-items:center;border:1px solid currentColor;border-radius:50%;background:radial-gradient(circle at 35% 30%,#60715955,#1a2826);font-size:20px;text-shadow:0 4px 4px #0008;filter:drop-shadow(0 3px 2px #0006)}.creature-info{display:grid;gap:4px;min-width:0}.creature-info strong{font:600 11px var(--display);color:#e2eadc}.creature-info small{color:#92a49a;font:8px var(--mono);letter-spacing:.4px}.creature-vitals{margin-left:auto;min-width:42px;text-align:right}.creature-hp{font:8px var(--mono);color:#c5d3bd}.creature-mini-meter{height:3px;margin-top:4px}.creature-mini-meter i{background:linear-gradient(90deg,#9acb85,#d4e995)}.team-note{margin:10px 0 0;color:#82948a;font-size:10px;line-height:1.45}.journal-panel{min-height:175px;flex:1;display:flex;flex-direction:column}.journal-mark{color:var(--lime);font-size:14px}.log{height:132px;overflow:auto;margin-top:11px;padding-right:4px;scrollbar-color:#40564b transparent;scrollbar-width:thin}.log-entry{padding:7px 0;border-bottom:1px solid #263632;color:#c1cdc2;font-size:10px;line-height:1.4}.log-entry:before{content:"›";color:var(--lime);padding-right:7px}.log-entry.old{color:#7e9087}.sidebar-foot{display:flex;justify-content:space-between;color:#687b72;font-size:8px;padding:2px 3px}.page-footer{display:flex;justify-content:space-between;padding:14px 0 20px;border-top:1px solid #253531;color:#778a80;font-size:8px;letter-spacing:.8px}
+
+/* Units are layered as small isometric miniatures; the sprite, shadow and rim
+   light stay separate so movement and combat remain readable on every tile. */
+.unit-figure{--unit-glow:#c2efa0;position:relative;z-index:2;width:100%;height:100%;display:grid;place-items:center;transform-style:preserve-3d;will-change:transform,filter}.unit-figure:before{content:"";position:absolute;left:50%;bottom:13%;width:62%;height:20%;transform:translateX(-50%) rotateX(58deg) translateZ(-5px);border-radius:50%;background:#070e0dcc;filter:blur(2px);box-shadow:0 3px 8px #0008}.unit-figure:after{content:"";position:absolute;left:50%;bottom:20%;width:50%;height:52%;transform:translateX(-50%) translateZ(-3px);border-radius:48% 48% 38% 38%;background:linear-gradient(135deg,#d9f4b433,#283c31aa 55%,#111d1d);border:1px solid #d6efb022;box-shadow:inset 2px 2px 4px #f4ffce22,inset -3px -4px 5px #07100e99,2px 4px 3px #08100d88}.sprite{position:relative;z-index:1;display:grid;place-items:center;line-height:1;font-family:var(--sans);font-size:clamp(17px,2.1vw,30px);filter:drop-shadow(1px 2px 0 #15221b) drop-shadow(0 5px 3px #0009);transform:translateY(-3px) translateZ(8px);text-shadow:0 0 12px #d9ffb733;animation:unitIdle 3.2s ease-in-out infinite}.player .sprite{font-size:clamp(19px,2.25vw,32px);filter:drop-shadow(2px 3px 0 #31452c) drop-shadow(0 6px 4px #000a)}.player:after{border-color:#d8f48766;background:linear-gradient(135deg,#efffc744,#526b3eaa 60%,#1d2c25);box-shadow:inset 2px 2px 6px #efffc944,inset -3px -4px 5px #07100e99,0 0 11px #d8f48733}.enemy{--unit-glow:#ff947d}.enemy:after{border-color:#ffb19a45;background:linear-gradient(135deg,#ffd0a833,#73443caa 60%,#2a2527);box-shadow:inset 2px 2px 5px #ffd4be33,inset -3px -4px 5px #160f11aa,0 0 9px #fa836033}.boss-tile .enemy:after{background:linear-gradient(135deg,#f8b6a044,#62333daa 60%,#211925);box-shadow:inset 2px 2px 5px #ffd4be44,inset -3px -4px 5px #160f11aa,0 0 15px #f57d7b55}.exit-unit{--unit-glow:#a5e3c5}.exit-unit .sprite{font-size:clamp(14px,1.8vw,23px);color:#b4e9c9;text-shadow:0 0 10px #9aebca99;animation:exitPulse 2.4s ease-in-out infinite}.item-unit{--unit-glow:#f2d783}.item-unit: