4:     { name: 'Mossbit', icon: '🐸', hp: 11, atk: 3, hue: '#a6d69d', type: 'FERN' },
5:     { name: 'Cinderling', icon: '🦊', hp: 10, atk: 4, hue: '#f1a17f', type: 'EMBER' },
