7:     { name: 'Fuzzlet', icon: '🐭', hp: 9, atk: 3, hue: '#d8b8ec', type: 'DUSK' },
8:     { name: 'Pebblit', icon: '🐢', hp: 15, atk: 2, hue: '#c4cc86', type: 'STONE' },
9:     { name: 'Glimmer', icon: '🦋', hp: 9, atk: 4, hue: '#e5c4f6', type: 'LUMEN' }
10:   ];
11:   const wildIcons = ['🦇', '🕷️', '🐍', '👾', '🦎', '🪲', '🐺', '🦂'];
12:   const names = ['Gloomwing', 'Weblet', 'Vinecoil', 'Nullbug', 'Skitter', 'Shardback', 'Nightpup', 'Scuttle'];
13:   const floorNotes = ['An archive reclaimed by root and time.','Water remembers every name it swallowed.','The glassroot bends light and direction.','A garden blooms where no sun can reach.','Every wandering signal converges here.'];
14:   const $ = id => document.getElementById(id);
15:   let state;
16:   let soundOn = false;
17:   let audio;
18:   let lastRenderedFloor = 0;
19:   let toastTimer;
20:   let renderedPositions = new Map();
21:   let combatEvents = [];
22:   const directions = { up: [0,-1], down: [0,1], left: [-1,0], right: [1,0] };
23: 
24:   function newGame() {
25:     state = { floor: 1, turn: 0, xp: 0, rank: 1, maxHp: 24, hp: 24, signals: 3, rations: 2, team: [{...species[0], hp: species[0].hp, maxHp: species[0].hp, id: 1}], enemies: [], items: [], walls: new Set(), player: {x:1,y:1}, logs: [], ended: false, bossDown: false };
26:     makeFloor();
27:     log('A faint signal pulses from below. Find the descent.');
28:     document.querySelector('.modal-card').classList.remove('result');
29:     $('modal-title').innerHTML='THE UNDERWILD<br><em>IS CALLING.</em>';
30:     $('start-button').innerHTML='BEGIN EXPEDITION <span>↗</span>';
31:     document.querySelector('.modal-copy').textContent='Descend into a shifting underground world. Befriend the things that live below, outlast the dark, and find your way to the heart of the signal.';
32:     document.querySelector('.howto').innerHTML='<span><kbd>WASD</kbd> MOVE & EXPLORE</span><span><kbd>SPACE</kbd> CAPTURE ADJACENT WILD</span>';
33:     render();
34:     $('modal').classList.remove('visible');
35:     lastRenderedFloor = state.floor;
36:   }
37:   function makeFloor() {
38:     renderedPositions.clear(); combatEvents = [];
39:     state.walls = new Set(); state.enemies = []; state.items = []; state.bossDown = false;
40:     state.player = {x:1,y:1};
41:     // Leave a clear upper corridor and the final descent route open; the rest of each floor shifts.
42:     for (let y=1;y<H-1;y++) for (let x=1;x<W-1;x++) {
43:       if ((y===1 && x<=11) || (x===11 && y>=1) || (x===1 && y<=6)) continue;
44:       if (Math.random() < .15) state.walls.add(key(x,y));
45:     }
46:     const candidates = [[4,2],[7,2],[9,3],[3,4],[6,5],[9,6],[4,7],[7,7],[2,6],[5,3],[8,5],[10,2],[2,3],[5,6]];
47:     const available = candidates.filter(([x,y])=>!state.walls.has(key(x,y)) && !(x===1&&y===1));
48:     shuffle(available);
49:     const enemyCount = Math.min(3 + Math.floor(state.floor/2), 6);
50:     for(let i=0;i<enemyCount && i<available.length;i++) {
51:       const [x,y]=available[i], idx=(Math.random()*wildIcons.length)|0;
52:       const boss = state.floor===5 && i===0;
53:       const hp = (boss ? 25 : 7 + state.floor*3 + ((Math.random()*4)|0));
54:       state.enemies.push({x,y,hp,maxHp:hp,atk:(boss?5:2+Math.floor(state.floor/2)),name:boss?'ROOTWRAITH':names[idx],icon:boss?'👹':wildIcons[idx],boss,id:Date.now()+i});
55:     }
56:     const itemSpots=available.slice(enemyCount, enemyCount+2);
57:     for(const [x,y] of itemSpots) state.items.push({x,y,type:Math.random()<.58?'ration':'signal'});
58:     state.exit={x:11,y:7};
59:   }
